// stores/cart.ts
import { ref, computed } from 'vue'
import { defineStore } from 'pinia'

export interface CartItem {
  id: string | number
  name: string
  price: number
  quantity: number
}

export const useCartStore = defineStore('cart', () => {
  const items = ref<CartItem[]>([])

  const total = computed(() =>
    items.value.reduce((sum, item) => sum + item.price * item.quantity, 0)
  )

  const itemCount = computed(() =>
    items.value.reduce((sum, item) => sum + item.quantity, 0)
  )

  function add(product: Omit<CartItem, 'quantity'>, quantity = 1) {
    const existing = items.value.find((item) => item.id === product.id)
    if (existing) {
      existing.quantity += quantity
    } else {
      items.value.push({ ...product, quantity })
    }
  }

  function remove(id: CartItem['id']) {
    items.value = items.value.filter((item) => item.id !== id)
  }

  function clear() {
    items.value = []
  }

  return { items, total, itemCount, add, remove, clear }
})
```

`add` increments the quantity if the product is already in the cart. `remove` drops the line item entirely. `total` is a computed getter. I also added `itemCount` and `clear`, which you can drop if you don't need them. I haven't run this.
